import{_ as a,c as t,o as r,ag as i}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Jump Master (Training)","description":"","frontmatter":{"title":"Jump Master (Training)"},"headers":[],"relativePath":"ai-ml/jump-master-training.md","filePath":"ai-ml/jump-master-training.md","lastUpdated":null}'),n={name:"ai-ml/jump-master-training.md"};function o(l,e,p,s,u,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="jump-master-training" tabindex="-1">Jump Master (Training) <a class="header-anchor" href="#jump-master-training" aria-label="Permalink to &quot;Jump Master (Training)&quot;">​</a></h1><h2 id="jump-master" tabindex="-1">Jump Master <a class="header-anchor" href="#jump-master" aria-label="Permalink to &quot;Jump Master&quot;">​</a></h2><h3 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h3><ul><li><p><a href="https://www.moore.army.mil/tenant/wtc/JMSTR.html" target="_blank" rel="noreferrer">Fort Moore Airbnore School References</a></p></li><li><p><a href="#"> MC-6 Nomenclature</a></p></li><li><p><a href="#">Standards.pdf</a></p></li><li><p><a href="https://www.moore.army.mil/tenant/wtc/Content/PDF/T-11%20Pre-Jump%20Study%20guide.pdf" target="_blank" rel="noreferrer">Pre-Jump Training</a></p></li></ul><p><a href="https://www.youtube.com/watch?v=drgwOIm9rsI" target="_blank" rel="noreferrer">YouTube Video</a></p><h3 id="getting-into-static-line-jump-master-course-sljmc" tabindex="-1">Getting into Static Line Jump Master Course (SLJMC) <a class="header-anchor" href="#getting-into-static-line-jump-master-course-sljmc" aria-label="Permalink to &quot;Getting into Static Line Jump Master Course (SLJMC)&quot;">​</a></h3><h3 id="white-slip" tabindex="-1">White Slip : <a class="header-anchor" href="#white-slip" aria-label="Permalink to &quot;White Slip :&quot;">​</a></h3><h4 id="nomenclature" tabindex="-1">Nomenclature: <a class="header-anchor" href="#nomenclature" aria-label="Permalink to &quot;Nomenclature:&quot;">​</a></h4><ul><li><p><a href="https://u.pcloud.link/publink/show?code=XZ2Kjc0Z5BrcVmmXQU7jvz6tcQ8upuKEKjg7" target="_blank" rel="noreferrer">Community Created Flashcards for MC-6</a></p><ul><li>Import this with Anki App</li></ul></li><li><p><a href="#">6-Nomenclature-JM Study.pdf</a></p></li><li><p><a href="#">6-Nomenclature-JM Study.pptx</a></p></li></ul><h3 id="airborne-study" tabindex="-1">Airborne Study <a class="header-anchor" href="#airborne-study" aria-label="Permalink to &quot;Airborne Study&quot;">​</a></h3><h3 id="five-points-of-performance" tabindex="-1">Five Points of Performance <a class="header-anchor" href="#five-points-of-performance" aria-label="Permalink to &quot;Five Points of Performance&quot;">​</a></h3><p>Remember with: Every Cat Loves Perfect Landings.</p><ol><li>(E) Proper Exit, Check Body Position, and Count</li></ol><h3 id="after-exiting-the-aircraft-get-into-a-tight-body-position-and-count-to-4" tabindex="-1">After exiting the aircraft, get into a tight body position and count to 4 <a class="header-anchor" href="#after-exiting-the-aircraft-get-into-a-tight-body-position-and-count-to-4" aria-label="Permalink to &quot;After exiting the aircraft, get into a tight body position and count to 4&quot;">​</a></h3><ol><li>(Canopy) Check Canopy and Gain Canopy Control</li></ol><h3 id="reach-up-grab-the-risers-and-do-a-full-360-degree-check-of-your-canopy" tabindex="-1">Reach up, grab the risers, and do a full 360 degree check of your canopy. <a class="header-anchor" href="#reach-up-grab-the-risers-and-do-a-full-360-degree-check-of-your-canopy" aria-label="Permalink to &quot;Reach up, grab the risers, and do a full 360 degree check of your canopy.&quot;">​</a></h3><ol><li>(Lookout) Keep a Lookout for Other Jumpers and Release Equipment</li></ol><h3 id="maintain-separation-from-fellow-jumpers-and-release-any-equipment" tabindex="-1">Maintain separation from fellow jumpers and release any equipment. <a class="header-anchor" href="#maintain-separation-from-fellow-jumpers-and-release-any-equipment" aria-label="Permalink to &quot;Maintain separation from fellow jumpers and release any equipment.&quot;">​</a></h3><ol><li>(Prepare to Land) Prepare to Land with a Parachute Landing Fall (PLF)</li></ol><h3 id="get-into-position-for-a-proper-plf-focusing-on-hitting-the-five-points-of-contact" tabindex="-1">Get into position for a proper PLF, focusing on hitting the five points of contact. <a class="header-anchor" href="#get-into-position-for-a-proper-plf-focusing-on-hitting-the-five-points-of-contact" aria-label="Permalink to &quot;Get into position for a proper PLF, focusing on hitting the five points of contact.&quot;">​</a></h3><ol><li>(Land) Land and Execute a PLF</li></ol><h3 id="upon-landing-conduct-a-proper-plf-by-hitting-all-five-points-balls-of-feet-calf-thigh-buttocks-and-the-pull-up-muscle" tabindex="-1">Upon landing, conduct a proper PLF by hitting all five points (balls of feet, calf, thigh, buttocks, and the pull-up muscle). <a class="header-anchor" href="#upon-landing-conduct-a-proper-plf-by-hitting-all-five-points-balls-of-feet-calf-thigh-buttocks-and-the-pull-up-muscle" aria-label="Permalink to &quot;Upon landing, conduct a proper PLF by hitting all five points (balls of feet, calf, thigh, buttocks, and the pull-up muscle).&quot;">​</a></h3><h3 id="jump-master-study" tabindex="-1">Jump Master Study <a class="header-anchor" href="#jump-master-study" aria-label="Permalink to &quot;Jump Master Study&quot;">​</a></h3><p>SAT <a href="#">Master Focused General Studies.wav</a></p><h3 id="jumpmaster-personell-inspection-jmpi" tabindex="-1">JumpMaster Personell Inspection (JMPI) <a class="header-anchor" href="#jumpmaster-personell-inspection-jmpi" aria-label="Permalink to &quot;JumpMaster Personell Inspection (JMPI)&quot;">​</a></h3><p>See <a href="#">3-21.220-JMPI.pdf</a></p><p><a href="/ai-ml/airborne-equipment-rigging.html">Equipment Rigging</a></p><h3 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h3><p>The following references will be utilized throughout the various periods of instruction taught during the Jumpmaster course</p><ul><li><p>AFI 11-231 – Computed Air Release Point Procedures</p></li><li><p>AFI 13-217 – Drop Zone and Landing Zone Operations</p></li><li><p>FM 3-21.38 – Pathfinder Operations</p></li><li><p>HQDA. (2015).FM 3-99 – Airborne and Air Assault Operations. URL: [* HQDA. (2018). TC 3-21.220 – Static Line Parachuting Techniques and Training. URL: <a href="https://armypubs.army.mil/epubs/DR_pubs/DR_a/ARN21085-TC_3-21.220-001-WEB-4.pdf" target="_blank" rel="noreferrer">https://armypubs.army.mil/epubs/DR_pubs/DR_a/ARN21085-TC_3-21.220-001-WEB-4.pdf</a>(<a href="https://armypubs.army.mil/epubs/DR_pubs/DR_a/pdf/web/fm3_99.pdf" target="_blank" rel="noreferrer">https://armypubs.army.mil/epubs/DR_pubs/DR_a/pdf/web/fm3_99.pdf</a>])</p></li><li><p>TM 10-1670-332-23&amp;P – Technical Manual Field Maintenance Manual Including Repair Parts And Special Tools List For Advanced Emergency Bailout Parachute (AEBP) System. URL (CAC Login Required): [* TM 10-1670-326-23&amp;P – Technical Manual Field Maintenance Manual Including Repair Parts And Special Tools List For T-11 Personnel Parachute System. URL (CAC Login Required): <a href="https://armypubs.army.mil/ProductMaps/PubForm/Details.aspx?PUB_ID=1001984" target="_blank" rel="noreferrer">https://armypubs.army.mil/ProductMaps/PubForm/Details.aspx?PUB_ID=1001984</a>(<a href="https://armypubs.army.mil/ProductMaps/PubForm/Details.aspx?PUB_ID=87089" target="_blank" rel="noreferrer">https://armypubs.army.mil/ProductMaps/PubForm/Details.aspx?PUB_ID=87089</a>])</p></li><li><p>HQDA. (2016).TM 4-48.03 – Airdrop of Supplies and Equipment: Rigging Containers. URL: [* TO 1C-130-9 – Technical Manual Cargo Loading Manual All USAF Series C-130 Aircraft</p></li><li><p>TO 1C-130J-9 – Technical Manual Cargo Loading Manual All USAF Series C-130J Aircraft</p></li><li><p>TO 1C-17A-1 – Supplemental Flight Manual Airdrop Mission Crew Manual USAF Series C-17A Aircraft</p></li></ul>',30)])])}const m=a(n,[["render",o]]);export{d as __pageData,m as default};
